import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.common.util.TriState;
import net.neoforged.neoforge.event.entity.player.ItemEntityPickupEvent;
import net.neoforged.neoforge.items.IItemHandler;
import net.neoforged.neoforge.network.codec.NeoForgeStreamCodecs;
import reliquary.block.PedestalBlock;
import reliquary.client.ClientInputHelper;
import reliquary.init.ModDataComponents;
import reliquary.init.ModItems;
import reliquary.item.util.IScrollableItem;
import reliquary.reference.Config;
import reliquary.util.*;

import javax.annotation.Nullable;

public class VoidTearItem extends ChargeableItem implements IScrollableItem {
	public VoidTearItem() {
		super(new Properties());
		NeoForge.EVENT_BUS.addListener(this::onItemPickup);
	}

	@Override
	public int getMaxStackSize(ItemStack stack) {
		return isEmpty(stack) ? 16 : 1;
	}

	@Override
	public boolean isFoil(ItemStack stack) {
		return !isShiftKeyDown() && super.isFoil(stack);
	}

	private boolean isShiftKeyDown() {
		return FMLEnvironment.dist == Dist.CLIENT && ClientInputHelper.isShiftKeyDown();
	}

	@Override
	protected void addMoreInformation(ItemStack voidTear, @Nullable HolderLookup.Provider registries, TooltipBuilder tooltipBuilder) {
		ItemStack contents = getTearContents(voidTear);

		if (isEmpty(voidTear)) {
			return;
		}

		tooltipBuilder
				.data(this, ".tooltip.mode",
						Component.translatable(TranslationHelper.transl(this) + ".mode." + getMode(voidTear).getSerializedName().toLowerCase())
								.withStyle(ChatFormatting.YELLOW),
						Component.translatable(TranslationHelper.translTooltip(this) + ".mode." + getMode(voidTear).getSerializedName().toLowerCase())
								.withStyle(ChatFormatting.GRAY))
				.description(TranslationHelper.translTooltip(this) + ".mode_change")
				.charge(this, ".tooltip.tear_quantity", contents.getHoverName().getString(), contents.getCount());
		if (isEnabled(voidTear)) {
			tooltipBuilder.absorbActive(contents.getHoverName().getString());
		} else {
			tooltipBuilder.absorb();
		}
	}

	@Override
	protected boolean hasMoreInformation(ItemStack stack) {
		return !isEmpty(stack);
	}

	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		ItemStack voidTear = player.getItemInHand(hand);

		if (!level.isClientSide) {
			BlockHitResult rayTraceResult = getPlayerPOVHitResult(level, player, ClipContext.Fluid.NONE);

			// not letting logic go through if player was sneak clicking inventory or was trying to place a block
			// noinspection ConstantConditions
			if (rayTraceResult != null && rayTraceResult.getType() == HitResult.Type.BLOCK
					&& (InventoryHelper.hasItemHandler(level, rayTraceResult.getBlockPos()) && player.isShiftKeyDown() || hasPlaceableBlock(voidTear))) {
				return new InteractionResultHolder<>(InteractionResult.PASS, voidTear);
			}

			if (isEmpty(voidTear)) {
				return rightClickEmpty(voidTear, player);
			}

			if (getItemQuantity(voidTear) == 0) {
				setEmpty(voidTear);
				return new InteractionResultHolder<>(InteractionResult.SUCCESS, voidTear);
			}

			if (player.isShiftKeyDown()) {
				return super.use(level, player, hand);
			}

			IItemHandler playerInventory = InventoryHelper.getMainInventoryItemHandlerFrom(player);
			if (attemptToEmptyIntoInventory(voidTear, player, playerInventory)) {
				player.level().playSound(null, player.blockPosition(), SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.PLAYERS, 0.1F,
						0.5F * (RandHelper.getRandomMinusOneToOne(player.level().random) * 0.7F + 1.2F));
				setEmpty(voidTear);
				return new InteractionResultHolder<>(InteractionResult.SUCCESS, voidTear);
			}
		}
		return new InteractionResultHolder<>(InteractionResult.PASS, voidTear);
	}

	private boolean hasPlaceableBlock(ItemStack voidTear) {
		return !isEmpty(voidTear) && getTearContents(voidTear).getItem() instanceof BlockItem;
	}

	private InteractionResultHolder<ItemStack> rightClickEmpty(ItemStack emptyVoidTear, Player player) {
		IItemHandler playerInventory = InventoryHelper.getMainInventoryItemHandlerFrom(player);
		ItemStack target = InventoryHelper.getTargetItem(emptyVoidTear, playerInventory);
		if (!target.isEmpty()) {
			boolean splitStack = emptyVoidTear.getCount() > 1;
			ItemStack filledTear = splitStack ? new ItemStack(this) : emptyVoidTear;
			if (!buildTear(filledTear, target, player, playerInventory, true)) {
				return new InteractionResultHolder<>(InteractionResult.PASS, emptyVoidTear);
			}
			if (splitStack) {
				emptyVoidTear.shrink(1);
			}
			player.level().playSound(null, player.blockPosition(), SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.PLAYERS, 0.1F,
					0.5F * (RandHelper.getRandomMinusOneToOne(player.level().random) * 0.7F + 1.2F));
			if (!splitStack) {
				return new InteractionResultHolder<>(InteractionResult.SUCCESS, filledTear);
			}
			InventoryHelper.addItemToPlayerInventory(player, filledTear);
			return new InteractionResultHolder<>(InteractionResult.SUCCESS, emptyVoidTear);
		}
		return new InteractionResultHolder<>(InteractionResult.PASS, emptyVoidTear);
	}

	private boolean buildTear(ItemStack voidTear, ItemStack target, Player player, IItemHandler inventory, boolean isPlayerInventory) {
		int quantity = InventoryHelper.getItemQuantity(target, inventory);
		if (isPlayerInventory) {
			int maxToConsume = Math.max(quantity - target.getMaxStackSize(), 1);
			quantity = player.isCreative()
					? maxToConsume
					: InventoryHelper.consumeItemStack(stack -> ItemStack.isSameItemSameComponents(target, stack), player, maxToConsume).getCount();
		} else {
			quantity = InventoryHelper.tryToRemoveFromInventory(target, inventory, Config.COMMON.items.voidTear.itemLimit.get());
		}
		if (quantity == 0) {
			return false;
		}
		setItemStack(voidTear, target);
		setItemQuantity(voidTear, quantity);

		// configurable auto-drain when created.
		if (Config.COMMON.items.voidTear.absorbWhenCreated.get()) {
			toggleEnabled(voidTear);
		}
		return true;
	}

	@Override
	public void inventoryTick(ItemStack voidTear, Level level, Entity entity, int slotNumber, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 5 != 0) {
			return;
		}
		if (isEnabled(voidTear)) {
			if (isEmpty(voidTear)) {
				setEmpty(voidTear); // fixes issue when creative inventory is opened and active tear gets messed up
				return;
			}

			ItemStack contents = getTearContents(voidTear);

			if (!contents.isEmpty()) {
				fillTear(voidTear, player, contents);
			} else {
				setEmpty(voidTear);
			}
		}
	}

	private void fillTear(ItemStack voidTear, Player player, ItemStack contents) {
		IItemHandler playerInventory = InventoryHelper.getMainInventoryItemHandlerFrom(player);
		int itemQuantity = InventoryHelper.getItemQuantity(contents, playerInventory);

		// doesn't absorb in creative mode. this is mostly for testing, it prevents the item from having unlimited *whatever* for eternity.
		if (getItemQuantity(voidTear) <= Config.COMMON.items.voidTear.itemLimit.get() && itemQuantity > getKeepQuantity(voidTear) && !player.isCreative()) {
			int consumed = InventoryHelper
					.consumeItemStack(stack -> ItemStack.isSameItemSameComponents(contents, stack), player, itemQuantity - getKeepQuantity(voidTear))
					.getCount();
			if (consumed > 0) {
				setItemQuantity(voidTear, getItemQuantity(voidTear) + consumed);
			}
		}
		if (getMode(voidTear) != Mode.NO_REFILL) {
			attemptToReplenish(player, voidTear);
		}
	}

	private void attemptToReplenish(Player player, ItemStack voidTear) {
		IItemHandler playerInventory = InventoryHelper.getMainInventoryItemHandlerFrom(player);
		if (fillFirstFirstStackFound(voidTear, playerInventory)) {
			return;
		}

		int slot;
		while (getItemQuantity(voidTear) > 1 && (slot = player.getInventory().getFreeSlot()) != -1) {
			ItemStack newStack = getTearContents(voidTear).copy();
			int quantityToDecrease = Math.min(newStack.getMaxStackSize(), getItemQuantity(voidTear) - 1);
			newStack.setCount(quantityToDecrease);
			player.getInventory().setItem(slot, newStack);
			setItemQuantity(voidTear, getItemQuantity(voidTear) - quantityToDecrease);
			if (getMode(voidTear) != Mode.FULL_INVENTORY) {
				return;
			}
		}
	}

	private boolean fillFirstFirstStackFound(ItemStack voidTear, IItemHandler h) {
		for (int slot = 0; slot < h.getSlots(); slot++) {
			ItemStack stackFound = h.getStackInSlot(slot);

			if (ItemStack.isSameItemSameComponents(stackFound, getTearContents(voidTear))) {
				int quantityToDecrease = Math.min(stackFound.getMaxStackSize() - stackFound.getCount(), getItemQuantity(voidTear) - 1);
				stackFound.grow(quantityToDecrease);
				setItemQuantity(voidTear, getItemQuantity(voidTear) - quantityToDecrease);
				if (getMode(voidTear) != Mode.FULL_INVENTORY) {
					return true;
				}
			}
		}
		return false;
	}

	@Override
	public InteractionResult onItemUseFirst(ItemStack stack, UseOnContext context) {
		Player player = context.getPlayer();
		if (player == null) {
			return InteractionResult.PASS;
		}
		InteractionHand hand = context.getHand();
		Level level = context.getLevel();
		BlockPos pos = context.getClickedPos();
		ItemStack voidTear = player.getItemInHand(hand);
		if (level.getBlockState(pos).getBlock() instanceof PedestalBlock) {
			return InteractionResult.PASS;
		}

		IItemHandler handler = level.getCapability(Capabilities.ItemHandler.BLOCK, pos, null);
		if (handler != null) {
			return processItemHandlerInteraction(player, hand, level, voidTear, handler);
		} else if (!level.isClientSide && hasPlaceableBlock(voidTear) && getItemQuantity(voidTear) > 0) {
			ItemStack containerItem = getTearContents(voidTear);
			BlockItem itemBlock = (BlockItem) containerItem.getItem();

			Direction face = context.getClickedFace();
			NoPlayerBlockItemUseContext noPlayerBlockItemUseContext = new NoPlayerBlockItemUseContext(level, pos, new ItemStack(itemBlock), face);
			if (noPlayerBlockItemUseContext.canPlace() && itemBlock.place(noPlayerBlockItemUseContext).consumesAction()) {
				setItemQuantity(voidTear, getItemQuantity(voidTear) - 1);
			}
		}
		return InteractionResult.PASS;
	}

	private InteractionResult processItemHandlerInteraction(Player player, InteractionHand hand, Level level, ItemStack voidTear, IItemHandler itemHandler) {
		if (!level.isClientSide) {
			if (isEmpty(voidTear)) {
				return onItemUseFirstEmpty(voidTear, itemHandler, player, hand);
			}

			// enabled == drinking mode, we're going to drain the inventory of items.
			if (isEnabled(voidTear)) {
				drainInventory(voidTear, player, itemHandler);
			} else {
				emptyIntoInventory(player, hand, voidTear, itemHandler);
			}
		}
		return InteractionResult.SUCCESS;
	}

	private void emptyIntoInventory(Player player, InteractionHand hand, ItemStack voidTear, IItemHandler itemHandler) {
		if (attemptToEmptyIntoInventory(voidTear, player, itemHandler)) {
			setEmpty(voidTear);
			player.setItemInHand(hand, voidTear);
		}
	}

	private InteractionResult onItemUseFirstEmpty(ItemStack emptyVoidTear, IItemHandler inventory, Player player, InteractionHand hand) {
		ItemStack target = InventoryHelper.getTargetItem(emptyVoidTear, inventory);
		if (!target.isEmpty()) {
			boolean splitStack = emptyVoidTear.getCount() > 1;
			ItemStack filledTear = splitStack ? new ItemStack(this) : emptyVoidTear;
			if (!buildTear(filledTear, target, player, inventory, false)) {
				return InteractionResult.PASS;
			}
			if (splitStack) {
				emptyVoidTear.shrink(1);
			}

			player.level().playSound(null, player.blockPosition(), SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.PLAYERS, 0.1F,
					0.5F * (RandHelper.getRandomMinusOneToOne(player.level().random) * 0.7F + 1.2F));
			if (!splitStack) {
				player.setItemInHand(hand, filledTear);
			} else {
				InventoryHelper.addItemToPlayerInventory(player, filledTear);
			}
			return InteractionResult.SUCCESS;
		}

		return InteractionResult.PASS;
	}

	private boolean attemptToEmptyIntoInventory(ItemStack stack, Player player, IItemHandler inventory) {
		ItemStack contents = getTearContents(stack).copy();
		contents.setCount(1);

		int quantity = getItemQuantity(stack);
		int maxNumberToEmpty = player.isShiftKeyDown() ? quantity : Math.min(contents.getMaxStackSize(), quantity);

		quantity -= InventoryHelper.tryToAddToInventory(contents, inventory, maxNumberToEmpty);

		if (quantity == 0) {
			player.level().playSound(null, player.blockPosition(), SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.PLAYERS, 0.1F,
					0.5F * (RandHelper.getRandomMinusOneToOne(player.level().random) * 0.7F + 1.8F));
			return true;
		} else {
			setItemQuantity(stack, quantity);
			player.level().playSound(null, player.blockPosition(), SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.PLAYERS, 0.1F,
					0.5F * (RandHelper.getRandomMinusOneToOne(player.level().random) * 0.7F + 1.2F));
			return false;
		}
	}

	private void drainInventory(ItemStack stack, Player player, IItemHandler inventory) {
		ItemStack contents = getTearContents(stack);
		int quantity = getItemQuantity(stack);

		int quantityDrained = InventoryHelper.tryToRemoveFromInventory(contents, inventory, Config.COMMON.items.voidTear.itemLimit.get() - quantity);

		if (quantityDrained <= 0) {
			return;
		}

		player.level().playSound(null, player.blockPosition(), SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.PLAYERS, 0.1F,
				0.5F * (RandHelper.getRandomMinusOneToOne(player.level().random) * 0.7F + 1.2F));

		setItemQuantity(stack, quantity + quantityDrained);
	}

	public static ItemStack getTearContents(ItemStack voidTear) {
		return ModItems.VOID_TEAR.get().getFromHandler(voidTear, handler -> handler.getStackInSlot(FIRST_SLOT));
	}

	@Override
	protected int getContainerSlotLimit(ItemStack stack, int slot) {
		return getItemQuantity(stack) == 0 ? 0 : Config.COMMON.items.voidTear.itemLimit.get();
	}

	@Override
	protected boolean isItemValidForContainerSlot(ItemStack containerStack, int slot, ItemStack stack) {
		return getFromHandler(containerStack,
				handler -> handler.getStackInSlot(FIRST_SLOT).isEmpty() || ItemStack.isSameItemSameComponents(getTearContents(containerStack), stack));
	}

	@Override
	public void addStoredCharge(ItemStack containerStack, int slot, int chargeToAdd, @Nullable ItemStack chargeStack) {
		if (slot > FIRST_SLOT) {
			return;
		}
		runOnHandler(containerStack, handler -> {
			ItemStack currentStack = handler.getStackInSlot(FIRST_SLOT);
			if (currentStack.isEmpty()) {
				if (chargeStack != null) {
					handler.setStackInSlot(slot, chargeStack);
				}
				return;
			}

			currentStack.setCount(Math.min(Config.COMMON.items.voidTear.itemLimit.get(), currentStack.getCount() + chargeToAdd));
			handler.setStackInSlot(FIRST_SLOT, currentStack);
		});
	}

	@Override
	public int getStoredCharge(ItemStack containerStack, int slot) {
		return slot == 0 ? getItemQuantity(containerStack) : 0;
	}

	private void setItemStack(ItemStack voidTear, ItemStack stack) {
		runOnHandler(voidTear, handler -> handler.setStackInSlot(FIRST_SLOT, stack));
	}

	private void setItemQuantity(ItemStack voidTear, int quantity) {
		runOnHandler(voidTear, handler -> {
			ItemStack stack = handler.getStackInSlot(FIRST_SLOT);
			stack.setCount(quantity);
			handler.setStackInSlot(FIRST_SLOT, stack);
		});
	}

	private int getItemQuantity(ItemStack voidTear) {
		return getFromHandler(voidTear, handler -> handler.getCountInSlot(FIRST_SLOT));
	}

	@Override
	public InteractionResult onMouseScrolled(ItemStack voidTear, Player player, double scrollDelta) {
		if (player.level().isClientSide) {
			return InteractionResult.PASS;
		}
		cycleMode(voidTear, scrollDelta > 0);
		return InteractionResult.SUCCESS;
	}

	public enum Mode implements StringRepresentable {
		ONE_STACK, FULL_INVENTORY, NO_REFILL;

		public static final Codec<Mode> CODEC = StringRepresentable.fromEnum(Mode::values);
		public static final StreamCodec<FriendlyByteBuf, Mode> STREAM_CODEC = NeoForgeStreamCodecs.enumCodec(Mode.class);

		@Override
		public String getSerializedName() {
			return name();
		}

		public Mode next() {
			return VALUES[(ordinal() + 1) % VALUES.length];
		}

		public Mode previous() {
			return VALUES[Math.floorMod(ordinal() - 1, VALUES.length)];
		}

		private static final Mode[] VALUES;

		static {
			ImmutableMap.Builder<String, Mode> builder = new ImmutableMap.Builder<>();
			for (Mode value : values()) {
				builder.put(value.getSerializedName(), value);
			}
			VALUES = values();
		}
	}

	public Mode getMode(ItemStack voidTear) {
		return voidTear.getOrDefault(ModDataComponents.VOID_TEAR_MODE, Mode.ONE_STACK);
	}

	private void setMode(ItemStack voidTear, Mode mode) {
		voidTear.set(ModDataComponents.VOID_TEAR_MODE, mode);
	}

	private void cycleMode(ItemStack voidTear, boolean next) {
		if (isEmpty(voidTear)) {
			return;
		}

		if (next) {
			setMode(voidTear, getMode(voidTear).next());
		} else {
			setMode(voidTear, getMode(voidTear).previous());
		}
	}

	private int getKeepQuantity(ItemStack voidTear) {
		Mode mode = getMode(voidTear);

		if (mode == Mode.NO_REFILL) {
			return 0;
		}
		if (mode == Mode.ONE_STACK) {
			return getTearContents(voidTear).getMaxStackSize();
		}

		return Integer.MAX_VALUE;
	}

	private void onItemPickup(ItemEntityPickupEvent.Pre event) {
		ItemStack pickedUpStack = event.getItemEntity().getItem();
		Player player = event.getPlayer();
		ItemEntity itemEntity = event.getItemEntity();

		for (int slot = 0; slot < player.getInventory().getContainerSize(); slot++) {
			ItemStack tearStack = player.getInventory().getItem(slot);
			if (tearStack.getItem() == this && isEnabled(tearStack) && tryToPickupWithTear(event, pickedUpStack, player, itemEntity, tearStack)) {
				break;
			}
		}
	}

	private boolean tryToPickupWithTear(ItemEntityPickupEvent.Pre event, ItemStack pickedUpStack, Player player, ItemEntity itemEntity, ItemStack tearStack) {
		int tearItemQuantity = getItemQuantity(tearStack);
		if (canAbsorbStack(pickedUpStack, tearStack)) {
			IItemHandler playerInventory = InventoryHelper.getMainInventoryItemHandlerFrom(player);
			int playerItemQuantity = InventoryHelper.getItemQuantity(pickedUpStack, playerInventory);

			if (playerItemQuantity + pickedUpStack.getCount() >= getKeepQuantity(tearStack) || player.getInventory().getFreeSlot() == -1) {
				setItemQuantity(tearStack, tearItemQuantity + pickedUpStack.getCount());
				if (!itemEntity.isSilent()) {
					RandomSource rand = itemEntity.level().random;
					itemEntity.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.ITEM_PICKUP, SoundSource.PLAYERS, 0.2F,
							(RandHelper.getRandomMinusOneToOne(rand) * 0.7F + 1.0F) * 2.0F);
				}
				itemEntity.discard();
				event.setCanPickup(TriState.FALSE);
				return true;
			}
		}
		return false;
	}

	boolean canAbsorbStack(ItemStack pickedUpStack, ItemStack tearStack) {
		return ItemStack.isSameItemSameComponents(getTearContents(tearStack), pickedUpStack)
				&& getItemQuantity(tearStack) + pickedUpStack.getCount() <= Config.COMMON.items.voidTear.itemLimit.get();
	}

	public boolean isEmpty(ItemStack voidTear) {
		return !voidTear.has(ModDataComponents.ENABLED) || getItemQuantity(voidTear) == 0;
	}

	private void setEmpty(ItemStack voidTear) {
		voidTear.remove(ModDataComponents.ENABLED);
		removeContainerContents(voidTear);
	}
}

package reliquary.item.component;

import com.google.common.base.Preconditions;
import net.minecraft.core.NonNullList;
import net.minecraft.core.component.DataComponentType;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.items.IItemHandlerModifiable;

import java.util.function.BiFunction;
import java.util.function.BiPredicate;

public class OversizedComponentItemHandler implements IItemHandlerModifiable {
	protected final ItemStack parent;
	protected final DataComponentType<OversizedItemContainerContents> component;
	protected final int size;
	private final BiFunction<ItemStack, Integer, Integer> getSlotLimit;
	private final BiPredicate<Integer, ItemStack> isItemValid;

	public OversizedComponentItemHandler(ItemStack parent, DataComponentType<OversizedItemContainerContents> component, int size,
			BiFunction<ItemStack, Integer, Integer> getSlotLimit, BiPredicate<Integer, ItemStack> isItemValid) {
		this.parent = parent;
		this.component = component;
		this.size = size;
		this.getSlotLimit = getSlotLimit;
		this.isItemValid = isItemValid;
		Preconditions.checkArgument(size <= OversizedItemContainerContents.MAX_SIZE,
				"The max size of OversizedItemContainerContents is " + OversizedItemContainerContents.MAX_SIZE + " slots.");
	}

	@Override
	public int getSlots() {
		return this.size;
	}

	@Override
	public ItemStack getStackInSlot(int slot) {
		OversizedItemContainerContents contents = this.getContents();
		return this.getStackFromContents(contents, slot);
	}

	public int getCountInSlot(int slot) {
		OversizedItemContainerContents contents = this.getContents();
		return contents.getSlots() > slot ? contents.getCountInSlot(slot) : 0;
	}

	@Override
	public void setStackInSlot(int slot, ItemStack stack) {
		this.validateSlotIndex(slot);
		if (!this.isItemValid(slot, stack)) {
			throw new RuntimeException("Invalid stack " + stack + " for slot " + slot + ")");
		} else {
			OversizedItemContainerContents contents = this.getContents();
			ItemStack existing = this.getStackFromContents(contents, slot);
			if (!ItemStack.matches(stack, existing)) {
				this.updateContents(contents, stack, slot);
			}
		}
	}

	public ItemStack insertItemOrAddIntoNewSlotIfNoStackMatches(ItemStack stack) {
		if (stack.isEmpty()) {
			return ItemStack.EMPTY;
		}

		for (int slot = 0; slot < getSlots(); slot++) {
			if (ItemStack.isSameItemSameComponents(stack, getStackInSlot(slot)) || (isItemValid(slot, stack) && getStackInSlot(slot).isEmpty())) {
				return insertItem(slot, stack, false);
			}
		}

		OversizedItemContainerContents contents = this.getContents();
		int newSlot = this.getSlots();
		NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots() + 1), ItemStack.EMPTY);
		if (!this.isItemValid(newSlot, stack)) {
			return stack;
		}
		contents.copyInto(list);
		int countToAdd = Math.min(stack.getCount(), getSlotLimit(list.size()));
		ItemStack stackToAdd = stack.copyWithCount(countToAdd);
		list.set(newSlot, stackToAdd);
		this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
		this.onContentsChanged(newSlot, ItemStack.EMPTY, stackToAdd);
		return countToAdd == stack.getCount() ? ItemStack.EMPTY : stack.copyWithCount(stack.getCount() - countToAdd);
	}

	public ItemStack extractItemAndRemoveSlotIfEmpty(int slot, int amount, boolean simulate) {
		return extractItemAndRemoveSlotIfEmpty(slot, amount, () -> {
		}, simulate);
	}

	public ItemStack extractItemAndRemoveSlotIfEmpty(int slot, int amount, Runnable onSlotRemoved, boolean simulate) {
		ItemStack stack = this.extractItem(slot, amount, simulate);
		if (!simulate && getStackInSlot(slot).isEmpty()) {
			OversizedItemContainerContents contents = this.getContents();
			NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots()), ItemStack.EMPTY);
			for (int i = 0; i < slot; i++) {
				list.set(i, contents.getSlots() > i ? contents.getStackInSlot(i) : ItemStack.EMPTY);
			}
			for (int i = slot; i < list.size(); i++) {
				list.set(i, contents.getSlots() > i + 1 ? contents.getStackInSlot(i + 1) : ItemStack.EMPTY);
			}
			this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
			this.onContentsChanged(slot, stack, ItemStack.EMPTY);
			onSlotRemoved.run();
		}
		return stack;

	}

	public void removeSlot(int slot) {
		OversizedItemContainerContents contents = this.getContents();
		NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots()), ItemStack.EMPTY);
		for (int i = 0, j = 0; i < size; i++) {
			if (i == slot)
				continue;
			list.set(j++, contents.getSlots() > i ? contents.getStackInSlot(i) : ItemStack.EMPTY);
		}
		this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
	}

	@Override
	public ItemStack insertItem(int slot, ItemStack toInsert, boolean simulate) {
		this.validateSlotIndex(slot);
		if (toInsert.isEmpty()) {
			return ItemStack.EMPTY;
		} else if (!this.isItemValid(slot, toInsert)) {
			return toInsert;
		} else {
			OversizedItemContainerContents contents = this.getContents();
			ItemStack existing = this.getStackFromContents(contents, slot);
			int insertLimit = this.getSlotLimit(slot);
			if (!existing.isEmpty()) {
				if (!ItemStack.isSameItemSameComponents(toInsert, existing)) {
					return toInsert;
				}

				insertLimit -= existing.getCount();
			}

			if (insertLimit <= 0) {
				return toInsert;
			} else {
				int inserted = Math.min(insertLimit, toInsert.getCount());
				if (!simulate) {
					this.updateContents(contents, toInsert.copyWithCount(existing.getCount() + inserted), slot);
				}

				return toInsert.copyWithCount(toInsert.getCount() - inserted);
			}
		}
	}

	@Override
	public ItemStack extractItem(int slot, int amount, boolean simulate) {
		this.validateSlotIndex(slot);
		if (amount == 0) {
			return ItemStack.EMPTY;
		} else {
			OversizedItemContainerContents contents = this.getContents();
			ItemStack existing = this.getStackFromContents(contents, slot);
			if (existing.isEmpty()) {
				return ItemStack.EMPTY;
			} else {
				int toExtract = Math.min(Math.min(amount, existing.getMaxStackSize()), existing.getCount());
				if (!simulate) {
					this.updateContents(contents, existing.copyWithCount(existing.getCount() - toExtract), slot);
				}

				return existing.copyWithCount(toExtract);
			}
		}
	}

	@Override
	public int getSlotLimit(int slot) {
		return getSlotLimit.apply(parent, slot);
	}

	@Override
	public boolean isItemValid(int slot, ItemStack stack) {
		return stack.isEmpty() || isItemValid.test(slot, stack) && stack.getItem().canFitInsideContainerItems();
	}

	protected void onContentsChanged(int slot, ItemStack oldStack, ItemStack newStack) {
	}

	protected OversizedItemContainerContents getContents() {
		if (this.parent.has(this.component)) {
			return this.parent.get(this.component);
		}

		return OversizedItemContainerContents.fromSize(size);
	}

	protected ItemStack getStackFromContents(OversizedItemContainerContents contents, int slot) {
		this.validateSlotIndex(slot);
		return contents.getSlots() <= slot ? ItemStack.EMPTY : contents.getStackInSlot(slot);
	}

	protected void updateContents(OversizedItemContainerContents contents, ItemStack stack, int slot) {
		this.validateSlotIndex(slot);
		NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots()), ItemStack.EMPTY);
		contents.copyInto(list);
		ItemStack oldStack = list.get(slot);
		list.set(slot, stack);
		this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
		this.onContentsChanged(slot, oldStack, stack);
	}

	protected final void validateSlotIndex(int slot) {
		if (slot < 0 || slot >= this.getSlots()) {
			throw new RuntimeException("Slot " + slot + " not in valid range - [0," + this.getSlots() + ")");
		}
	}
}

package reliquary.item.component;

import com.google.common.collect.Iterables;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.NonNullList;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import reliquary.util.CodecHelper;

import java.util.ArrayList;
import java.util.List;
import java.util.OptionalInt;
import java.util.stream.Stream;

public final class OversizedItemContainerContents {
	private static final int NO_SLOT = -1;
	public static final int MAX_SIZE = 256;
	public static final OversizedItemContainerContents EMPTY = new OversizedItemContainerContents(NonNullList.create());
	public static final Codec<OversizedItemContainerContents> CODEC;
	public static final StreamCodec<RegistryFriendlyByteBuf, OversizedItemContainerContents> STREAM_CODEC;
	private final NonNullList<ItemStack> items;
	private final int hashCode;

	private OversizedItemContainerContents(NonNullList<ItemStack> items) {
		if (items.size() > MAX_SIZE) {
			throw new IllegalArgumentException("Got " + items.size() + " items, but maximum is " + MAX_SIZE);
		} else {
			this.items = items;
			this.hashCode = ItemStack.hashStackList(items);
		}
	}

	private OversizedItemContainerContents(int p_331689_) {
		this(NonNullList.withSize(p_331689_, ItemStack.EMPTY));
	}

	private OversizedItemContainerContents(List<ItemStack> items) {
		this(items.size());

		for (int i = 0; i < items.size(); ++i) {
			this.items.set(i, items.get(i));
		}

	}

	private static OversizedItemContainerContents fromSlots(List<Slot> slots) {
		OptionalInt maxIndex = slots.stream().mapToInt(Slot::index).max();
		if (maxIndex.isEmpty()) {
			return EMPTY;
		} else {
			OversizedItemContainerContents contents = new OversizedItemContainerContents(maxIndex.getAsInt() + 1);
			slots.forEach((slot) -> contents.items.set(slot.index(), slot.item()));
			return contents;
		}
	}

	public static OversizedItemContainerContents fromSize(int size) {
		return new OversizedItemContainerContents(size);
	}

	public static OversizedItemContainerContents fromItems(List<ItemStack> p_340879_) {
		int i = findLastNonEmptySlot(p_340879_);
		if (i == NO_SLOT) {
			return EMPTY;
		} else {
			OversizedItemContainerContents contents = new OversizedItemContainerContents(i + 1);

			for (int index = 0; index <= i; ++index) {
				contents.items.set(index, p_340879_.get(index).copy());
			}

			return contents;
		}
	}

	private static int findLastNonEmptySlot(List<ItemStack> items) {
		for (int i = items.size() - 1; i >= 0; --i) {
			if (!items.get(i).isEmpty()) {
				return i;
			}
		}

		return NO_SLOT;
	}

	private List<Slot> asSlots() {
		List<Slot> list = new ArrayList<>();

		for (int i = 0; i < this.items.size(); ++i) {
			ItemStack itemstack = this.items.get(i);
			if (!itemstack.isEmpty()) {
				list.add(new Slot(i, itemstack));
			}
		}

		return list;
	}

	public void copyInto(NonNullList<ItemStack> p_330513_) {
		for (int i = 0; i < p_330513_.size(); ++i) {
			ItemStack itemstack = i < this.items.size() ? this.items.get(i) : ItemStack.EMPTY;
			p_330513_.set(i, itemstack.copy());
		}

	}

	public ItemStack copyOne() {
		return this.items.isEmpty() ? ItemStack.EMPTY : this.items.getFirst().copy();
	}

	public Stream<ItemStack> stream() {
		return this.items.stream().map(ItemStack::copy);
	}

	public Stream<ItemStack> nonEmptyStream() {
		return this.items.stream().filter((item) -> !item.isEmpty()).map(ItemStack::copy);
	}

	public Iterable<ItemStack> nonEmptyItems() {
		return Iterables.filter(this.items, item -> !item.isEmpty());
	}

	public Iterable<ItemStack> nonEmptyItemsCopy() {
		return Iterables.transform(this.nonEmptyItems(), ItemStack::copy);
	}

	public boolean equals(Object other) {
		if (this == other) {
			return true;
		} else {
			if (other instanceof OversizedItemContainerContents contents) {
				return ItemStack.listMatches(this.items, contents.items);
			}

			return false;
		}
	}

	public int hashCode() {
		return this.hashCode;
	}

	public int getSlots() {
		return this.items.size();
	}

	public ItemStack getStackInSlot(int slot) {
		this.validateSlotIndex(slot);
		return this.items.get(slot).copy();
	}

	public int getCountInSlot(int slot) {
		this.validateSlotIndex(slot);
		return this.items.get(slot).getCount();
	}

	public Item getStackInSlotItem(int slot) {
		this.validateSlotIndex(slot);
		return this.items.get(slot).getItem();
	}

	private void validateSlotIndex(int slot) {
		if (slot < 0 || slot >= this.getSlots()) {
			throw new UnsupportedOperationException("Slot " + slot + " not in valid range - [0," + this.getSlots() + ")");
		}
	}

	static {
		CODEC = Slot.CODEC.sizeLimitedListOf(MAX_SIZE).xmap(OversizedItemContainerContents::fromSlots, OversizedItemContainerContents::asSlots);
		STREAM_CODEC = ItemStack.OPTIONAL_STREAM_CODEC.apply(ByteBufCodecs.list(MAX_SIZE)).map(OversizedItemContainerContents::new,
				(contents) -> contents.items);
	}

	record Slot(int index, ItemStack item) {
		public static final Codec<Slot> CODEC = RecordCodecBuilder
				.create((instance) -> instance
						.group(Codec.intRange(0, 255).fieldOf("slot").forGetter(Slot::index),
								CodecHelper.OVERSIZED_ITEM_STACK_CODEC.orElse(ItemStack.EMPTY).fieldOf("item").forGetter(Slot::item))
						.apply(instance, Slot::new));
	}
}

