package reliquary.util;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.NonNullList;
import net.minecraft.world.Containers;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.items.IItemHandler;
import net.neoforged.neoforge.items.wrapper.PlayerMainInvWrapper;
import reliquary.item.ToggleableItem;

import javax.annotation.Nullable;

import java.util.*;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;

public class InventoryHelper {
	private InventoryHelper() {
	}

	public static void spawnItemStack(Level level, BlockPos pos, ItemStack stack) {
		Containers.dropItemStack(level, pos.getX(), pos.getY(), pos.getZ(), stack);
	}

	public static ItemStack getTargetItem(ItemStack self, IItemHandler inventory) {
		if (self.isEmpty()) {
			return ItemStack.EMPTY;
		}

		ItemStack targetItem = ItemStack.EMPTY;
		int itemQuantity = 0;
		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			ItemStack stack = inventory.getStackInSlot(slot);
			if (ItemStack.isSameItemSameComponents(self, stack) || stack.getMaxStackSize() == 1) {
				continue;
			}
			if (getItemQuantity(stack, inventory) > itemQuantity) {
				itemQuantity = getItemQuantity(stack, inventory);
				targetItem = stack.copy();
			}
		}
		return targetItem;
	}

	public static int getItemQuantity(ItemStack stack, IItemHandler inventory) {
		if (stack.isEmpty()) {
			return 0;
		}

		int itemQuantity = 0;
		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			ItemStack newStack = inventory.getStackInSlot(slot);
			if (ItemStack.isSameItemSameComponents(stack, newStack)) {
				itemQuantity += newStack.getCount();
			}
		}
		return itemQuantity;
	}

	public static ItemStack consumeItemStack(Predicate<ItemStack> itemMatches, Player player, int count) {
		return extractFromInventory(itemMatches, count, getMainInventoryItemHandlerFrom(player), false);
	}

	public static ItemStack extractFromInventory(Predicate<ItemStack> itemMatches, int count, IItemHandler inventory, boolean simulate) {
		ItemStack ret = ItemStack.EMPTY;
		int slots = inventory.getSlots();
		for (int slot = 0; slot < slots && ret.getCount() < count; slot++) {
			ItemStack slotStack = inventory.getStackInSlot(slot);
			if (itemMatches.test(slotStack) && (ret.isEmpty() || ItemStack.isSameItemSameComponents(ret, slotStack))) {
				int toExtract = Math.min(slotStack.getCount(), count - ret.getCount());
				ItemStack extractedStack = inventory.extractItem(slot, toExtract, simulate);
				if (ret.isEmpty()) {
					ret = extractedStack;
				} else {
					ret.setCount(ret.getCount() + extractedStack.getCount());
				}
			}
		}
		return ret;
	}

	public static int tryToRemoveFromInventory(ItemStack contents, IItemHandler inventory, int maxToRemove) {
		int remaining = maxToRemove;

		ItemStack stackToExtract = contents.copy();
		int currentStackCount = Math.min(remaining, stackToExtract.getMaxStackSize());
		stackToExtract.setCount(currentStackCount);

		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			if (inventory.getStackInSlot(slot).isEmpty()) {
				continue;
			}

			// storage drawers compatibility loop
			while (inventory.getStackInSlot(slot).getCount() > 0 && ItemStack.isSameItemSameComponents(inventory.getStackInSlot(slot), contents)
					&& remaining > 0) {
				ItemStack extractedStack = inventory.extractItem(slot, Math.min(maxToRemove, inventory.getStackInSlot(slot).getCount()), false);
				if (extractedStack.getCount() == 0) {
					break; // just in case some item handler shows stacks that can't be extracted
				}

				remaining -= extractedStack.getCount();

				stackToExtract = contents.copy();
				currentStackCount = Math.min(remaining, stackToExtract.getMaxStackSize());
				stackToExtract.setCount(currentStackCount);
			}

			if (remaining <= 0) {
				break;
			}
		}
		return maxToRemove - remaining;
	}

	public static void runOnInventoryAt(Level level, BlockPos pos, Consumer<IItemHandler> run) {
		IItemHandler itemHandler = getInventoryAtPos(level, pos, null);
		if (itemHandler == null) {
			return;
		}
		run.accept(itemHandler);
	}

	@Nullable
	public static IItemHandler getInventoryAtPos(Level level, BlockPos pos, @Nullable Direction side) {
		return level.getCapability(Capabilities.ItemHandler.BLOCK, pos, side);
	}

	@Nullable
	public static IItemHandler getItemHandlerFrom(Player player) {
		return player.getCapability(Capabilities.ItemHandler.ENTITY);
	}

	public static IItemHandler getMainInventoryItemHandlerFrom(Player player) {
		return new PlayerMainInvWrapper(player.getInventory());
	}

	public static void executeOnItemHandlerAt(Level level, BlockPos pos, BlockState state, BlockEntity blockEntity, Consumer<IItemHandler> run) {
		executeOnItemHandlerAt(level, pos, state, blockEntity, handler -> {
			run.accept(handler);
			return null;
		}, null);
	}

	public static <T> T executeOnItemHandlerAt(Level level, BlockPos pos, BlockState state, @Nullable BlockEntity blockEntity, Function<IItemHandler, T> run,
			@Nullable T defaultReturnValue) {
		return executeOnItemHandlerAt(level, pos, state, blockEntity, null, run, defaultReturnValue);
	}

	private static <T> T executeOnItemHandlerAt(Level level, BlockPos pos, BlockState state, @Nullable BlockEntity blockEntity, @Nullable Direction side,
			Function<IItemHandler, T> run, @Nullable T defaultReturnValue) {
		IItemHandler itemHandler = level.getCapability(Capabilities.ItemHandler.BLOCK, pos, state, blockEntity, side);

		if (itemHandler != null) {
			return run.apply(itemHandler);
		}

		// noinspection DataFlowIssue - sometimes null may be produced based on default value being null, ignoring here not to have to deal with nullability
		// check everywhere this is used
		return defaultReturnValue;
	}

	public static int insertIntoInventory(ItemStack contents, IItemHandler inventory) {
		return tryToAddToInventory(contents, inventory, contents.getCount());
	}

	public static int tryToAddToInventoryAtPos(ItemStack contents, Level level, BlockPos pos, Direction side, int maxToAdd) {
		IItemHandler inventory = getInventoryAtPos(level, pos, side);
		if (inventory == null) {
			return 0;
		}

		return tryToAddToInventory(contents, inventory, maxToAdd);
	}

	public static int tryToAddToInventory(ItemStack contents, IItemHandler inventory, int maxToAdd) {
		int inventorySize = inventory.getSlots();

		int remaining = maxToAdd;
		ItemStack stackToInsert = contents.copy();
		int currentStackCount = Math.min(remaining, stackToInsert.getMaxStackSize());
		stackToInsert.setCount(currentStackCount);
		for (int slot = 0; slot < inventorySize; slot++) {
			// storage drawers and similar storage blocks support
			while (inventory.insertItem(slot, stackToInsert, true).getCount() < stackToInsert.getCount()) {
				ItemStack remainingStack = inventory.insertItem(slot, stackToInsert, false);
				if (remainingStack.getCount() < currentStackCount) {
					remaining -= (currentStackCount - remainingStack.getCount());
					if (remaining <= 0) {
						return maxToAdd;
					}
					stackToInsert = contents.copy();
					currentStackCount = Math.min(remaining, stackToInsert.getMaxStackSize());
					stackToInsert.setCount(currentStackCount);
				}
			}
		}

		return maxToAdd - remaining;
	}

	public static void tryRemovingLastStack(IItemHandler inventory, Level level, BlockPos pos) {
		for (int i = inventory.getSlots() - 1; i >= 0; i--) {
			if (!inventory.getStackInSlot(i).isEmpty()) {
				ItemStack stack = inventory.getStackInSlot(i).copy();
				inventory.extractItem(i, stack.getCount(), false);
				if (level.isClientSide) {
					return;
				}
				ItemEntity itemEntity = new ItemEntity(level, pos.getX() + 0.5D, pos.getY() + 1D, pos.getZ() + 0.5D, stack);
				level.addFreshEntity(itemEntity);
				break;
			}
		}
	}

	public static boolean tryAddingPlayerCurrentItem(Player player, IItemHandler inventory, InteractionHand hand) {
		ItemStack stack = player.getItemInHand(hand).copy();
		stack.setCount(1);

		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			ItemStack remainingStack = inventory.insertItem(slot, stack, false);
			if (remainingStack.isEmpty()) {
				player.getItemInHand(hand).shrink(1);

				if (player.getItemInHand(hand).getCount() == 0) {
					player.setItemInHand(hand, ItemStack.EMPTY);
				}

				player.getInventory().setChanged();
				return true;
			}
		}

		return false;
	}

	public static ItemStack getItemFromAllPlayerHandlers(Player player, Item item) {
		return PlayerInventoryProvider.get().getFromPlayerInventoryHandlers(player, (stack, result) -> {
			if (stack.isEmpty() || stack.getItem() != item) {
				return ItemStack.EMPTY;
			}

			return stack;
		}, result -> !result.isEmpty(), () -> ItemStack.EMPTY);
	}

	public static boolean playerHasItem(Player player, Item item) {
		return playerHasItem(player, item, false);
	}

	public static boolean playerHasItem(Player player, Item item, boolean checkEnabled) {
		return PlayerInventoryProvider.get().getFromPlayerInventoryHandlers(player, (stack, result) -> {
			if (stack.isEmpty()) {
				return false;
			}
			return stack.getItem() == item
					&& (!(checkEnabled && stack.getItem() instanceof ToggleableItem) || ((ToggleableItem) stack.getItem()).isEnabled(stack));
		}, result -> result, () -> false);
	}

	public static ItemStack getCorrectItemFromEitherHand(Player player, Item item) {
		return getHandHoldingCorrectItem(player, item).map(player::getItemInHand).orElse(ItemStack.EMPTY);
	}

	private static Optional<InteractionHand> getHandHoldingCorrectItem(Player player, Item item) {
		if (player.getMainHandItem().getItem() == item) {
			return Optional.of(InteractionHand.MAIN_HAND);
		}

		if (player.getOffhandItem().getItem() == item) {
			return Optional.of(InteractionHand.OFF_HAND);
		}
		return Optional.empty();
	}

	public static void addItemToPlayerInventory(Player player, ItemStack stack) {
		for (int i = 0; i < player.getInventory().items.size(); ++i) {
			if (player.getInventory().getItem(i).isEmpty()) {
				player.getInventory().setItem(i, stack);
				return;
			}
		}
		player.level().addFreshEntity(new ItemEntity(player.level(), player.getX(), player.getY(), player.getZ(), stack));
	}

	public static NonNullList<ItemStack> getItemStacks(IItemHandler inventory) {
		NonNullList<ItemStack> ret = NonNullList.create();

		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			ret.add(inventory.getStackInSlot(slot));
		}
		return ret;
	}

	public static void dropInventoryItems(Level level, BlockPos pos, IItemHandler inventory) {
		dropInventoryItems(level, pos.getX(), pos.getY(), pos.getZ(), inventory);
	}

	private static void dropInventoryItems(Level level, double x, double y, double z, IItemHandler inventory) {
		for (int i = 0; i < inventory.getSlots(); ++i) {
			ItemStack itemstack = inventory.getStackInSlot(i);

			if (!itemstack.isEmpty()) {
				Containers.dropItemStack(level, x, y, z, itemstack);
			}
		}
	}

	public static boolean hasItemHandler(Level level, BlockPos pos) {
		return executeOnItemHandlerAt(level, pos, level.getBlockState(pos), null, handler -> true, false);
	}
}

package com.enderio.enderio.api.soul;

import com.mojang.logging.LogUtils;
import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.nbt.Tag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.ExtraCodecs;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.Leashable;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.animal.Bee;
import org.jetbrains.annotations.Nullable;
import org.slf4j.Logger;

import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Represents a stored soul, derived from a {@link LivingEntity}.
 * @param entityTag the entity's NBT tag.
 */
public record Soul(@Nullable EntityType<?> entityType, CompoundTag entityTag) {

    // Keys that should not be compared or saved
    // Note be careful adding new things to this list - it will affect saves.
    private static final List<String> IGNORED_KEYS = List.of(
        Entity.ID_TAG, // We store the entity type separately to the entity data.
        "Air",
        "Brain",
        "DeathTime",
        "FallDistance",
        "FallFlying",
        "HurtByTimestamp",
        "HurtTime",
        "Motion",
        "OnGround",
        "PortalCooldown",
        "Pos",
        "Rotation",
        "SleepingX",
        "SleepingY",
        "SleepingZ",
        Leashable.LEASH_TAG,
        Entity.UUID_TAG
    );

    // Do not compare obviously unreasonable NBT Keys
    private static final List<String> IGNORED_KEYS_DURING_COMPARISON = List.of(
        // TODO: need to check for any other tags that should be ignored.
        // Perhaps make this configurable?
        Bee.TAG_CANNOT_ENTER_HIVE_TICKS,
        Bee.TAG_TICKS_SINCE_POLLINATION,
        Bee.TAG_CROPS_GROWN_SINCE_POLLINATION,
        Bee.TAG_HIVE_POS,
        Entity.PASSENGERS_TAG
    );

    public static final Soul EMPTY = new Soul(Optional.empty(), new CompoundTag());

    private static final Codec<Soul> NEW_CODEC;

    private static final Codec<Soul> OLD_CODEC = RecordCodecBuilder.create(
        instance -> instance.group(
            CompoundTag.CODEC.fieldOf("entityTag").forGetter(Soul::entityTag)
        ).apply(instance, Soul::new));

    public static final Codec<Soul> OPTIONAL_CODEC;

    static {
        // Moved to optionalFieldOf with an optional wrapper to ensure that we can load a null entity_type, but throw it as invalid.
        // Otherwise it'll attempt to deserialize null and fail deep inside the codec logic.
        // TODO: 26.1: Change entityType to be an Optional perhaps? Not doing anything further here to avoid breaking API.
        Codec<Soul> newCodec = RecordCodecBuilder.create(
            instance -> instance.group(
                BuiltInRegistries.ENTITY_TYPE.byNameCodec().optionalFieldOf("entity_type").forGetter(soul -> Optional.ofNullable(soul.entityType())),
                CompoundTag.CODEC.fieldOf("entity_tag").forGetter(Soul::entityTag)
            ).apply(instance, Soul::new));

        // Only apply validator to the main codec, we'll skip it on the optional codec for now in case
        // TODO: 26.1: simplify this back down.
        NEW_CODEC = newCodec.validate((soul) -> soul.entityType == null ? DataResult.error(() -> "Entity type cannot be null") : DataResult.success(soul));

        OPTIONAL_CODEC = ExtraCodecs
            .optionalEmptyMap(Codec.withAlternative(newCodec, OLD_CODEC))
            .xmap(opt -> opt.filter(s -> !s.isEmpty()).orElse(EMPTY), soul -> soul.isEmpty() ? Optional.empty() : Optional.of(soul));
    }

    public static final Codec<Soul> CODEC = Codec.withAlternative(NEW_CODEC, OLD_CODEC);

    public static final StreamCodec<RegistryFriendlyByteBuf, Soul> STREAM_CODEC = StreamCodec.composite(
        ByteBufCodecs.registry(Registries.ENTITY_TYPE),
        Soul::entityType,
        ByteBufCodecs.COMPOUND_TAG,
        Soul::entityTag,
        Soul::new
    );

    public Soul {
        // Remove tags we don't want
        IGNORED_KEYS.forEach(entityTag::remove);
    }

    private Soul(Optional<EntityType<?>> entityTypeOpt, CompoundTag entityTag) {
        this(entityTypeOpt.orElse(null), entityTag);
    }

    // Legacy data support.
    private Soul(CompoundTag tag) {
        // Note: doesn't remove ID from the tag to ensure backwards compatibility.
        // TODO: 1.22 - remove this.
        this(BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.parse(tag.getString(Entity.ID_TAG))), tag);
    }

    public static final StreamCodec<RegistryFriendlyByteBuf, Soul> OPTIONAL_STREAM_CODEC = new StreamCodec<>() {
        @Override
        public Soul decode(RegistryFriendlyByteBuf byteBuf) {
            boolean hasEntity = byteBuf.readBoolean();
            if (!hasEntity) {
                return EMPTY;
            }

            return STREAM_CODEC.decode(byteBuf);
        }

        @Override
        public void encode(RegistryFriendlyByteBuf o, Soul soul) {
            o.writeBoolean(soul.hasEntity());
            if (soul.hasEntity()) {
                STREAM_CODEC.encode(o, soul);
            }
        }
    };

    public static Soul of(LivingEntity entity) {
        var entityTag = new CompoundTag();
        entity.saveWithoutId(entityTag);
        return new Soul(entity.getType(), entityTag);
    }

    public static Soul of(ResourceLocation entityType) {
        return of(BuiltInRegistries.ENTITY_TYPE.get(entityType));
    }

    public static Soul of(EntityType<?> entityType) {
        return new Soul(entityType, new CompoundTag());
    }

    public static boolean isSameEntity(Soul soul1, Soul soul2) {
        return Objects.equals(soul1.entityType(), soul2.entityType());
    }

    public static boolean isSameEntity(Soul soul, LivingEntity livingEntity) {
        return isSameEntity(soul, livingEntity.getType());
    }

    public static boolean isSameEntity(Soul soul, EntityType<?> entityType) {
        return Objects.equals(soul.entityType(), entityType);
    }

    public static boolean isSameEntitySameTag(Soul soul1, Soul soul2) {
        if (!isSameEntity(soul1, soul2)) {
            return false;
        }

        return isSameTag(soul1.entityTag(), soul2.entityTag());
    }

    public static boolean isSameEntitySameTag(Soul soul, LivingEntity livingEntity) {
        if (!isSameEntity(soul, livingEntity)) {
            return false;
        }

        var entityTagToCompare = new CompoundTag();
        livingEntity.saveWithoutId(entityTagToCompare);
        return isSameTag(soul.entityTag(), entityTagToCompare);
    }

    private static boolean isSameTag(CompoundTag tag1, CompoundTag tag2) {
        var allKeys = Stream.concat(tag1.getAllKeys().stream(), tag2.getAllKeys().stream()).collect(Collectors.toSet());
        for (var key : allKeys) {
            if (IGNORED_KEYS.contains(key) ||
                IGNORED_KEYS_DURING_COMPARISON.contains(key)) {
                continue;
            }

            if (!Objects.equals(tag1.get(key), tag2.get(key))) {
                return false;
            }
        }

        return true;
    }

    public boolean hasEntity() {
        return entityType != null;
    }

    public boolean isEmpty() {
        return entityType == null;
    }

    /**
     * @throws IllegalStateException if the soul is empty.
     * @return
     */
    public ResourceLocation entityTypeId() {
        if (isEmpty()) {
            throw new IllegalStateException("Cannot get Entity Type ID from empty StoredEntityData");
        }

        return BuiltInRegistries.ENTITY_TYPE.getKey(entityType);
    }

    public CompoundTag getEntityTagWithId() {
        var tag = entityTag.copy();
        tag.putString(Entity.ID_TAG, entityTypeId().toString());
        return tag;
    }

    public Soul copy() {
        if (isEmpty()) {
            return EMPTY;
        }

        return new Soul(entityType(), entityTag.copy());
    }

    public Soul copyOnlyType() {
        if (isEmpty()) {
            return EMPTY;
        }

        return of(entityType());
    }

    private static final Logger LOGGER = LogUtils.getLogger();

    public Tag save(HolderLookup.Provider lookupProvider) {
        if (!this.hasEntity()) {
            throw new IllegalStateException("Cannot encode empty StoredEntityData");
        } else {
            return CODEC.encodeStart(lookupProvider.createSerializationContext(NbtOps.INSTANCE), this).getOrThrow();
        }
    }

    public Tag saveOptional(HolderLookup.Provider lookupProvider) {
        return this.hasEntity() ? save(lookupProvider) : new CompoundTag();
    }

    public static Optional<Soul> parse(HolderLookup.Provider lookupProvider, Tag tag) {
        return CODEC.parse(lookupProvider.createSerializationContext(NbtOps.INSTANCE), tag)
            .resultOrPartial(error -> LOGGER.error("Tried to load invalid StoredEntityData: '{}'", error));
    }

    public static Soul parseOptional(HolderLookup.Provider lookupProvider, CompoundTag tag) {
        return tag.isEmpty() ? EMPTY : parse(lookupProvider, tag).orElse(EMPTY);
    }
}

package com.enderio.enderio.api.soul;

import com.enderio.enderio.api.EnderIOCapabilities;
import com.enderio.enderio.api.soul.binding.SoulBindable;
import net.minecraft.world.item.ItemStack;
import org.jetbrains.annotations.ApiStatus;

import java.util.Optional;

/**
 * Some helper methods for interacting with {@link SoulBindable} capabilities.
 */
@ApiStatus.AvailableSince("8.0")
@ApiStatus.Experimental
public class SoulBoundUtils {
    /**
     * Test whether the {@code itemStack} supports soul binding.
     * @implNote This tests both whether the {@code itemStack} supports the capability and that {@link SoulBindable#canBind()} is true.
     * @param itemStack the item to test.
     * @return whether the item can be bound.
     */
    public static boolean canBindSoul(ItemStack itemStack) {
        var soulBindable = itemStack.getCapability(EnderIOCapabilities.SOUL_BINDABLE_ITEM);
        if (soulBindable == null) {
            return false;
        }

        return soulBindable.canBind();
    }

    /**
     * Test whether the {@code soul} can be bound to the {@code itemStack}.
     * @param itemStack the item stack to bind to.
     * @param soul the soul to test.
     * @return whether it can be bound.
     */
    public static boolean canBindSoul(ItemStack itemStack, Soul soul) {
        var soulBindable = itemStack.getCapability(EnderIOCapabilities.SOUL_BINDABLE_ITEM);
        if (soulBindable == null) {
            return false;
        }

        return soulBindable.canBind() && soulBindable.isSoulValid(soul);
    }

    /**
     * Get the soul bound to the {@code itemStack} or {@link Soul#EMPTY}.
     * @param itemStack the stack to get a soul for.
     * @return the bound soul, or {@link Soul#EMPTY} if there is no soul bound.
     */
    public static Soul getBoundSoul(ItemStack itemStack) {
        var soulBindable = itemStack.getCapability(EnderIOCapabilities.SOUL_BINDABLE_ITEM);
        if (soulBindable == null) {
            return Soul.EMPTY;
        }

        return soulBindable.getBoundSoul();
    }

    /**
     * Whether the {@code itemStack} has a soul bound to it.
     * @param itemStack the stack to check.
     * @return whether there is a bound soul.
     */
    public static boolean isBound(ItemStack itemStack) {
        var soulBindable = itemStack.getCapability(EnderIOCapabilities.SOUL_BINDABLE_ITEM);
        if (soulBindable == null) {
            return false;
        }

        return soulBindable.hasSoul();
    }

    /**
     * Attempt to bind a {@code soul} to the {@code itemStack}.
     * @param itemStack the stack to bind to.
     * @param soul the soul to be bound.
     * @return whether the binding was successful
     */
    public static boolean tryBindSoul(ItemStack itemStack, Soul soul) {
        var soulBindable = itemStack.getCapability(EnderIOCapabilities.SOUL_BINDABLE_ITEM);
        if (soulBindable == null) {
            return false;
        }

        // Short-circuit if we're already bound.
        if (Soul.isSameEntitySameTag(soulBindable.getBoundSoul(), soul)) {
            return true;
        }

        return tryBindSoul(soulBindable, soul);
    }

    /**
     * Attempt to bind a {@code soul} to the {@code soulBindable}.
     * @param soulBindable the object to bind to.
     * @param soul the soul to be bound.
     * @return whether the binding was successful
     */
    public static boolean tryBindSoul(SoulBindable soulBindable, Soul soul) {
        if (!soulBindable.canBind() || !soulBindable.isSoulValid(soul)) {
            return false;
        }

        soulBindable.bindSoul(soul);
        return true;
    }

    /**
     * Attempts to bind a soul to the given {@code itemStack}. If the {@code itemStack} cannot
     * have a soul bound to it then it is returned unchanged.
     * If the binding fails, the method returns an empty {@link Optional}.
     * If the soul is successfully bound, the method returns the original {@code itemStack}.
     *
     * @param itemStack The item stack that should have the soul bound to it.
     * @param soul      The soul to be bound to the {@code itemStack}.
     * @return An {@link Optional} containing the original {@code itemStack} if binding was successful or is not possible,
     *         or an empty {@link Optional} if binding failed.
     */
    public static Optional<ItemStack> getBoundIfCapable(ItemStack itemStack, Soul soul) {
        // Copy so we don't bind the original input.
        ItemStack result = itemStack.copy();

        // If there's no binding possible, allow it through
        var soulBindable = result.getCapability(EnderIOCapabilities.SOUL_BINDABLE_ITEM);
        if (soulBindable == null) {
            return Optional.of(result);
        }

        if (tryBindSoul(soulBindable, soul)) {
            return Optional.of(result);
        }

        return Optional.empty();
    }
}

package com.enderio.enderio.content.tools.vials;

import com.enderio.core.client.item.AdvancedTooltipProvider;
import com.enderio.core.common.util.TooltipUtil;
import com.enderio.enderio.EnderIO;
import com.enderio.enderio.api.soul.Soul;
import com.enderio.enderio.api.soul.SoulBoundUtils;
import com.enderio.enderio.config.base.BaseConfig;
import com.enderio.enderio.content.tools.ToolsLang;
import com.enderio.enderio.foundation.util.EntityCaptureUtils;
import com.enderio.enderio.init.EIODataComponents;
import com.enderio.enderio.init.EIOItems;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.dispenser.BlockSource;
import net.minecraft.core.dispenser.OptionalDispenseItemBehavior;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
